mkdir -p "$TEMP/s" && cat > "$TEMP/s/d.py" <<'EOF'
import re,os,collections
mods=['pulsar-broker','pulsar-broker-common','pulsar-client','pulsar-client-api','pulsar-common','pulsar-metadata','managed-ledger']
files=[]
for m in mods:
    for r,_,fs in os.walk(m+'/src/main/java'):
        for f in fs:
            if f.endswith('.java'): files.append(os.path.join(r,f))
def strip(s):
    s=re.sub(r'/\*.*?\*/',' ',s,flags=re.S)
    s=re.sub(r'"(\\.|[^"\\\n])*"','""',s)
    s=re.sub(r'//[^\n]*',' ',s)
    return s
types={} # fqn -> file
info={}
for f in files:
    s=strip(open(f,encoding='utf8',errors='ignore').read())
    p=re.search(r'^\s*package\s+([\w.]+);',s,re.M)
    pkg=p.group(1) if p else ''
    if not pkg.startswith('org.apache.pulsar'): continue
    tops=re.findall(r'^(?:public\s+|final\s+|abstract\s+|sealed\s+|static\s+)*(?:class|interface|enum|record|@interface)\s+(\w+)',s,re.M)
    for t in tops: types[pkg+'.'+t]=f
    info[f]=(pkg,s,tops)
bypkg=collections.defaultdict(dict)
for fq in types:
    pk,n=fq.rsplit('.',1); bypkg[pk][n]=fq
cnt=collections.Counter()
for f,(pkg,s,tops) in info.items():
    body=re.sub(r'^\s*(package|import)\s[^;]*;','',s,flags=re.M)
    idents=set(re.findall(r'[A-Za-z_]\w*',body))
    deps=set()
    imps=re.findall(r'^\s*import\s+(static\s+)?([\w.]+)(\.\*)?;',s,re.M)
    cand={}
    for n,fq in bypkg[pkg].items(): cand[n]=fq
    explicit={}
    for st,name,wild in imps:
        if wild:
            if st:
                # static import of members of class
                if name in types: deps.add(name)
                continue
            for n,fq in bypkg.get(name,{}).items():
                if n not in explicit: cand.setdefault(n,fq) if n not in cand else None
                cand[n]=cand[n] if n in bypkg[pkg] else fq
        else:
            parts=name.split('.')
            # find longest prefix that is a top-level type
            for i in range(len(parts),0,-1):
                pre='.'.join(parts[:i])
                if pre in types:
                    if not st and i==len(parts): explicit[parts[-1]]=pre
                    if st or i<len(parts): 
                        deps.add(pre)  # nested/static import
                    else: explicit[parts[-1]]=pre
                    break
    for n,fq in explicit.items(): cand[n]=fq
    for n,fq in cand.items():
        if n in idents and (n in explicit or True): deps.add(fq)
    for fq in explicit.values(): 
        if fq.rsplit('.',1)[1] in idents: deps.add(fq)
    # fully qualified usages
    for m in re.finditer(r'org\.apache\.pulsar(?:\.\w+)+',body):
        parts=m.group(0).split('.')
        for i in range(len(parts),3,-1):
            pre='.'.join(parts[:i])
            if pre in types: deps.add(pre);break
    own={pkg+'.'+t for t in tops}
    for d in deps-own: cnt[d]+=1
for fq,c in cnt.most_common(15): print(c,fq)
EOF
